951|local void flush_pending(z_streamp strm) {
952|    unsigned len;
953|    deflate_state *s = strm->state;
954|
955|    _tr_flush_bits(s);
956|    len = s->pending > strm->avail_out ? strm->avail_out :
957|                                         (unsigned)s->pending;
958|    if (len == 0) return;
959|
960|    zmemcpy(strm->next_out, s->pending_out, len);
961|    strm->next_out  += len;
962|    s->pending_out  += len;
963|    strm->total_out += len;
964|    strm->avail_out -= len;
965|    s->pending      -= len;
966|    if (s->pending == 0) {
967|        s->pending_out = s->pending_buf;
968|    }
969|}

