944|/* =========================================================================
945| * Flush as much pending output as possible. All deflate() output, except for
946| * some deflate_stored() output, goes through this function so some
947| * applications may wish to modify it to avoid allocating a large
948| * strm->next_out buffer and copying into it. (See also read_buf()).
949| */
950|local void flush_pending(z_streamp strm) {
951|    unsigned len;
952|    deflate_state *s = strm->state;
953|
954|    _tr_flush_bits(s);
955|    len = s->pending > strm->avail_out ? strm->avail_out :
956|                                         (unsigned)s->pending;
957|    if (len == 0) return;
958|
959|    zmemcpy(strm->next_out, s->pending_out, len);
960|    strm->next_out  += len;
961|    s->pending_out  += len;
