170|#define CLEAR_HASH(s) \
171|    do { \
172|        s->head[s->hash_size - 1] = NIL; \
173|        zmemzero(s->head, (unsigned)(s->hash_size - 1)*sizeof(*s->head)); \
174|        s->slid = 0; \
175|    } while (0)
