544|#ifdef GZIP
545|                                           s->status != GZIP_STATE &&
546|#endif
547|                                           s->status != EXTRA_STATE &&
548|                                           s->status != NAME_STATE &&
549|                                           s->status != COMMENT_STATE &&
550|                                           s->status != HCRC_STATE &&
551|                                           s->status != BUSY_STATE &&
552|                                           s->status != FINISH_STATE))
