557|/* ========================================================================= */
558|int ZEXPORT deflateSetDictionary(z_streamp strm, const Bytef *dictionary,
559|                                 uInt  dictLength) {
560|    deflate_state *s;
561|    uInt str, n;
562|    int wrap;
563|    unsigned avail;
564|    z_const unsigned char *next;
565|
566|    if (deflateStateCheck(strm) || dictionary == Z_NULL)
567|        return Z_STREAM_ERROR;
568|    s = strm->state;
569|    wrap = s->wrap;
570|    if (wrap == 2 || (wrap == 1 && s->status != INIT_STATE) || s->lookahead)
571|        return Z_STREAM_ERROR;
572|
573|    /* when using zlib wrappers, compute Adler-32 for provided dictionary */
574|    if (wrap == 1)
575|        strm->adler = adler32(strm->adler, dictionary, dictLength);
576|    s->wrap = 0;                    /* avoid computing Adler-32 in read_buf */
577|
578|    /* if dictionary would fill window, just replace the history */
579|    if (dictLength >= s->w_size) {
580|        if (wrap == 0) {            /* already empty otherwise */
581|            CLEAR_HASH(s);
582|            s->strstart = 0;
583|            s->block_start = 0L;
584|            s->insert = 0;
585|        }
586|        dictionary += dictLength - s->w_size;  /* use the tail */
587|        dictLength = s->w_size;
588|    }
589|
590|    /* insert dictionary into window and hash */
591|    avail = strm->avail_in;
592|    next = strm->next_in;
593|    strm->avail_in = dictLength;
594|    strm->next_in = (z_const Bytef *)dictionary;
595|    fill_window(s);
596|    while (s->lookahead >= MIN_MATCH) {
597|        str = s->strstart;
598|        n = s->lookahead - (MIN_MATCH-1);
599|        do {
600|            UPDATE_HASH(s, s->ins_h, s->window[str + MIN_MATCH-1]);
601|#ifndef FASTEST
602|            s->prev[str & s->w_mask] = s->head[s->ins_h];
603|#endif
604|            s->head[s->ins_h] = (Pos)str;
605|            str++;
606|        } while (--n);
607|        s->strstart = str;
608|        s->lookahead = MIN_MATCH-1;
609|        fill_window(s);
610|    }
611|    s->strstart += s->lookahead;
612|    s->block_start = (long)s->strstart;
613|    s->insert = s->lookahead;
614|    s->lookahead = 0;
615|    s->match_length = s->prev_length = MIN_MATCH-1;
616|    s->match_available = 0;
617|    strm->next_in = next;
618|    strm->avail_in = avail;
619|    s->wrap = wrap;
620|    return Z_OK;
621|}
