746|int ZEXPORT deflatePrime(z_streamp strm, int bits, int value) {
747|    deflate_state *s;
748|    int put;
749|
750|    if (deflateStateCheck(strm)) return Z_STREAM_ERROR;
751|    s = strm->state;
752|#ifdef LIT_MEM
753|    if (bits < 0 || bits > 16 ||
754|        (uchf *)s->d_buf < s->pending_out + ((Buf_size + 7) >> 3))
755|        return Z_BUF_ERROR;
756|#else
757|    if (bits < 0 || bits > 16 ||
758|        s->sym_buf < s->pending_out + ((Buf_size + 7) >> 3))
759|        return Z_BUF_ERROR;
760|#endif
761|    do {
762|        put = Buf_size - s->bi_valid;
763|        if (put > bits)
764|            put = bits;
765|        s->bi_buf |= (ush)((value & ((1 << put) - 1)) << s->bi_valid);
766|        s->bi_valid += put;
767|        _tr_flush_bits(s);
768|        value >>= put;
769|        bits -= put;
770|    } while (bits);
