833|/* =========================================================================
834| * For the default windowBits of 15 and memLevel of 8, this function returns a
835| * close to exact, as well as small, upper bound on the compressed size. This
836| * is an expansion of ~0.03%, plus a small constant.
837| *
838| * For any setting other than those defaults for windowBits and memLevel, one
839| * of two worst case bounds is returned. This is at most an expansion of ~4% or
840| * ~13%, plus a small constant.
841| *
842| * Both the 0.03% and 4% derive from the overhead of stored blocks. The first
843| * one is for stored blocks of 16383 bytes (memLevel == 8), whereas the second
844| * is for stored blocks of 127 bytes (the worst case memLevel == 1). The
845| * expansion results from five bytes of header for each stored block.
846| *
847| * The larger expansion of 13% results from a window size less than or equal to
848| * the symbols buffer size (windowBits <= memLevel + 7). In that case some of
849| * the data being compressed may have slid out of the sliding window, impeding
850| * a stored block from being emitted. Then the only choice is a fixed or
851| * dynamic block, where a fixed block limits the maximum expansion to 9 bits
852| * per 8-bit byte, plus 10 bits for every block. The smallest block size for
853| * which this can occur is 255 (memLevel == 2).
854| *
855| * Shifts are used to approximate divisions, for speed.
856| */
857|z_size_t ZEXPORT deflateBound_z(z_streamp strm, z_size_t sourceLen) {
858|    deflate_state *s;
859|    z_size_t fixedlen, storelen, wraplen, bound;
860|
861|    /* upper bound for fixed blocks with 9-bit literals and length 255
862|       (memLevel == 2, which is the lowest that may not use stored blocks) --
863|       ~13% overhead plus a small constant */
864|    fixedlen = sourceLen + (sourceLen >> 3) + (sourceLen >> 8) +
865|               (sourceLen >> 9) + 4;
866|    if (fixedlen < sourceLen)
867|        fixedlen = (z_size_t)-1;
868|
869|    /* upper bound for stored blocks with length 127 (memLevel == 1) --
870|       ~4% overhead plus a small constant */
871|    storelen = sourceLen + (sourceLen >> 5) + (sourceLen >> 7) +
872|               (sourceLen >> 11) + 7;
873|    if (storelen < sourceLen)
874|        storelen = (z_size_t)-1;
875|
876|    /* if can't get parameters, return larger bound plus a wrapper */
877|    if (deflateStateCheck(strm)) {
878|        bound = fixedlen > storelen ? fixedlen : storelen;
879|        return bound + 18 < bound ? (z_size_t)-1 : bound + 18;
880|    }
881|
882|    /* compute wrapper length */
883|    s = strm->state;
884|    switch (s->wrap < 0 ? -s->wrap : s->wrap) {
885|    case 0:                                 /* raw deflate */
886|        wraplen = 0;
887|        break;
888|    case 1:                                 /* zlib wrapper */
889|        wraplen = 6 + (s->strstart ? 4 : 0);
890|        break;
891|#ifdef GZIP
892|    case 2:                                 /* gzip wrapper */
893|        wraplen = 18;
894|        if (s->gzhead != Z_NULL) {          /* user-supplied gzip header */
895|            Bytef *str;
896|            if (s->gzhead->extra != Z_NULL)
897|                wraplen += 2 + s->gzhead->extra_len;
898|            str = s->gzhead->name;
899|            if (str != Z_NULL)
900|                do {
901|                    wraplen++;
902|                } while (*str++);
903|            str = s->gzhead->comment;
904|            if (str != Z_NULL)
905|                do {
906|                    wraplen++;
907|                } while (*str++);
908|            if (s->gzhead->hcrc)
909|                wraplen += 2;
910|        }
911|        break;
912|#endif
913|    default:                                /* for compiler happiness */
914|        wraplen = 18;
915|    }
916|
917|    /* if not default parameters, return one of the conservative bounds */
918|    if (s->w_bits != 15 || s->hash_bits != 8 + 7) {
919|        bound = s->w_bits <= s->hash_bits && s->level ? fixedlen :
920|                                                        storelen;
921|        return bound + wraplen < bound ? (z_size_t)-1 : bound + wraplen;
922|    }
923|
924|    /* default settings: return tight bound for that case -- ~0.03% overhead
925|       plus a small constant */
926|    bound = sourceLen + (sourceLen >> 12) + (sourceLen >> 14) +
927|            (sourceLen >> 25) + 13 - 6 + wraplen;
928|    return bound < sourceLen ? (z_size_t)-1 : bound;
929|}
930|uLong ZEXPORT deflateBound(z_streamp strm, uLong sourceLen) {
931|    z_size_t bound = deflateBound_z(strm, sourceLen);
932|    return (uLong)bound != bound ? (uLong)-1 : (uLong)bound;
933|}
