338|static void test_flush(Byte *compr, uLong *comprLen) {
339|    z_stream c_stream; /* compression stream */
340|    int err;
341|    uInt len = (uInt)strlen(hello)+1;
342|
343|    c_stream.zalloc = zalloc;
344|    c_stream.zfree = zfree;
345|    c_stream.opaque = (voidpf)0;
346|
347|    err = deflateInit(&c_stream, Z_DEFAULT_COMPRESSION);
348|    CHECK_ERR(err, "deflateInit");
349|
350|    c_stream.next_in  = (z_const unsigned char *)hello;
351|    c_stream.next_out = compr;
352|    c_stream.avail_in = 3;
353|    c_stream.avail_out = (uInt)*comprLen;
354|    err = deflate(&c_stream, Z_FULL_FLUSH);
355|    CHECK_ERR(err, "deflate");
356|
357|    compr[3]++; /* force an error in first compressed block */
358|    c_stream.avail_in = len - 3;
359|
360|    err = deflate(&c_stream, Z_FINISH);
